function renderProducts(filter="all",query=""){
 const grid=$("productGrid");if(!grid)return;
 const sort=$("sortProducts")?.value||"featured";
 const q=String(query||$("productSearch")?.value||"").trim().toLocaleLowerCase("bn");
 let list=products.filter(p=>{
  const categoryMatch=filter==="all"||p.category===filter;
  const hay=[p.name,p.bn,p.brand,p.category,p.tag,p.desc,p.size].join(" ").toLocaleLowerCase("bn");
  return categoryMatch&&(!q||hay.includes(q));
 });
 if(sort==="low")list.sort((x,y)=>x.price-y.price);else if(sort==="high")list.sort((x,y)=>y.price-x.price);
 const count=$("productCount");if(count)count.textContent=list.length+"টি পণ্য";
 grid.innerHTML=list.length?list.map(p=>'<article class="product-card" data-product="'+p.id+'" tabindex="0"><div class="product-visual"><span class="product-tag">'+p.tag+'</span><img src="'+p.img+'" alt="'+pname(p)+'" loading="lazy" onerror="this.onerror=null;this.src=\'https://placehold.co/600x600/f0eee8/222?text=KORDESH+Product\'"></div><div class="product-info"><span class="product-category">'+p.brand+' · '+p.size+'</span><h3>'+pname(p)+'</h3><p>'+p.desc+'</p><div class="product-bottom"><span class="product-price">'+money(p.price)+'</span><button class="add-button" data-add="'+p.id+'">'+t("add")+' +</button></div><button class="details-link" data-detail="'+p.id+'">'+t("details")+' ↗</button></div></article>').join(""):'<p class="empty-cart">কোনো পণ্য পাওয়া যায়নি। অন্য নামে খুঁজে দেখুন।</p>';
}
function renderCart(){
 $("cartCount").textContent=cart.reduce((s,x)=>s+x.qty,0);$("cartSubtotal").textContent=money(cart.reduce((s,x)=>s+x.qty*x.price,0));
 $("cartItems").innerHTML=cart.length?cart.map(i=>{const p=products.find(x=>x.id===i.id);return '<div class="cart-line"><img class="cart-thumb" src="'+p.img+'" alt=""><div><h4>'+pname(p)+'</h4><small>'+money(p.price)+'</small><div class="qty-controls"><button data-qty="-1" data-id="'+p.id+'">−</button><span>'+i.qty+'</span><button data-qty="1" data-id="'+p.id+'">+</button></div></div><button class="remove-item" data-remove="'+p.id+'">'+t("remove")+'</button></div>'}).join(""):'<p class="empty-cart">'+t("empty")+'</p>';
}
function saveCart(){localStorage.setItem("kordesh-cart",JSON.stringify(cart));renderCart()}
let toastTimer;
function showToast(message){let toast=$("cartToast");if(!toast)return;toast.textContent=message;toast.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove("show"),2000)}
function addToCart(id){const p=products.find(x=>x.id===id);if(!p)return;const item=cart.find(x=>x.id===id);if(item)item.qty=Math.min(99,item.qty+1);else cart.push({id,qty:1,price:p.price});saveCart();showToast("কার্টে যোগ হয়েছে");}
